      <div>
        <div className="flex items-center gap-2 mb-8 px-2 text-white font-bold text-lg">
          <div className="w-6 h-6 rounded-md bg-gradient-to-tr from-teal-400 to-blue-500" /> Nimbus
        </div>
        <nav className="space-y-1">
          {nav.map(item => (
            <button key={item} className={`w-full text-left px-3 py-2 rounded-lg text-sm ${
              item === active ? 'bg-slate-800 text-white font-medium' : 'hover:text-slate-200'
            }`}>{item}</button>
          ))}
        </nav>
      </div>

export function StatCard({ title, value, detail, detailColor = 'text-emerald-600' }) {
  return (
    <div className="bg-white rounded-xl border border-slate-100 p-6 flex-1 shadow-sm">
      <span className="text-sm text-slate-500">{title}</span>
      <h2 className="text-3xl font-bold text-slate-900 mt-2">{value}</h2>
      <p className={`text-xs mt-2 font-medium ${detailColor}`}>{detail}</p>
    </div>
  );
}

export function StatusBadge({ status }) {
  const map = {
    'On track': 'bg-emerald-50 text-emerald-700',
    'At risk': 'bg-amber-50 text-amber-700',
    'Blocked': 'bg-rose-50 text-rose-700',
  };
  return (
    <span className={`px-2.5 py-0.5 rounded-full text-xs font-medium ${map[status] || 'bg-slate-100'}`}>
      {status}
    </span>
  );
}

import { NextResponse } from 'next/server';
import prisma from '@/lib/prisma';

export async function GET() {
  const [projects, activities] = await Promise.all([
    prisma.project.findMany({ take: 5, orderBy: { updatedAt: 'desc' } }),
    prisma.activity.findMany({ take: 5, orderBy: { createdAt: 'desc' } }),
  ]);
  return NextResponse.json({ projects, activities });
}

